import { useEffect, useRef } from "react";
import type { ChatMessage } from "@/store/chat";
import { messageRowKey } from "./useConversationViewport";

/** Arrival eligibility belongs to the committed conversation, never loaded history. */
export function useMessageArrivalMotion(
  scope: string,
  messages: ChatMessage[],
  context = false,
) {
  const committed = useRef({ scope, seen: new Set<string>(), primed: false });
  // Snapshot before the effect: virtual rows can render after the parent commits.
  const baseline = committed.current;
  const eligible = baseline.scope === scope && baseline.primed && !context;
  const seen = baseline.seen;
  useEffect(() => {
    const previous = committed.current;
    const nextSeen = new Set(previous.scope === scope ? previous.seen : []);
    messages.forEach((message, index) => nextSeen.add(messageRowKey(message, index)));
    committed.current = {
      scope,
      seen: nextSeen,
      primed: (previous.scope === scope && previous.primed) || messages.length > 0,
    };
  }, [messages, scope]);
  return (message: ChatMessage, index: number) =>
    eligible &&
    (message.arrivalKind === "live" ||
      (message.fromMe && message.pending === true && !!message.clientId)) &&
    !seen.has(messageRowKey(message, index));
}
